 @Test void entryVersionLimitFailsWithoutPartialReport(){for(int i=2;i<=201;i++)version(i,null);fails(422,()->reports.report(1,uid("student")));}
 @Test void feedbackLimitFailsWithoutPartialReport(){var batch=new ArrayList<Object[]>();for(int i=0;i<500;i++)batch.add(new Object[]{uid("teacher"),"批注 "+i,Store.now()});s.db.batchUpdate("INSERT INTO feedback(submission_id,teacher_id,paragraph_id,original_text,indicator_code,body,resolved,created_at) VALUES(1,?,'p-gap','原文','C2',?,FALSE,?)",batch);fails(422,()->reports.report(1,uid("student")));}
 @Test void actionLimitFailsWithoutPartialReport(){var batch=new ArrayList<Object[]>();for(int i=0;i<1501;i++)batch.add(new Object[]{uid("student"),Store.now()});s.db.batchUpdate("INSERT INTO feedback_action(feedback_id,user_id,action_type,body,created_at) VALUES(1,?,'REPLY','说明',?)",batch);fails(422,()->reports.report(1,uid("student")));}
 @Test void reportReturnsSchemaGeneratedTimeAndEvidenceCounts(){var report=reports.report(1,uid("student"));assertEquals(1,report.get("schemaVersion"));assertEquals("ENTRY_PROGRESS_REPORT",report.get("kind"));assertNotNull(Instant.parse((String)report.get("generatedAt")));assertEquals(1,n((Map<String,Object>)versions(report).getFirst().get("evidence_counts"),"PASS"));assertFalse(((List<?>)report.get("notes")).isEmpty());}
 @Test void completedReportIsAnImmutableObjectSnapshot(){var before=reports.report(1,uid("student"));domain.action(1,"RESOLVE","已确认",uid("teacher"));grade(1,91);assertEquals(1,n(summary(before),"open_feedback"));assertEquals(76,((Number)summary(before).get("latest_score")).doubleValue(),.001);assertEquals(91,((Number)summary(reports.report(1,uid("student"))).get("latest_score")).doubleValue(),.001);}
